cat > alphametics.go <<'EOF'
package alphametics

import (
	"errors"
	"strings"
)

type term struct {
	letter byte
	count  int
}

type column struct {
	terms  []term
	res    byte
	hasRes bool
}

func Solve(puzzle string) (map[string]int, error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, errors.New("puzzle must contain exactly one == operator")
	}

	raw := strings.Split(parts[0], "+")
	addends := make([]string, 0, len(raw))
	for _, w := range raw {
		w = strings.TrimSpace(w)
		if w == "" {
			return nil, errors.New("empty addend in puzzle")
		}
		addends = append(addends, w)
	}
	result := strings.TrimSpace(parts[1])
	if result == "" {
		return nil, errors.New("empty result in puzzle")
	}

	// Collect letters and letters that may not be zero.
	letters := make(map[byte]bool)
	leading := make(map[byte]bool)
	for _, w := range append(addends, result) {
		for i := 0; i < len(w); i++ {
			letters[w[i]] = true
		}
		if len(w) > 1 {
			leading[w[0]] = true
		}
	}
	if len(letters) > 10 {
		return nil, errors.New("too many distinct letters")
	}

	// Build column information, least significant column first.
	maxLen := len(result)
	for _, w := range addends {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	cols := make([]column, maxLen)
	for i := 0; i < maxLen; i++ {
		counts := make(map[byte]int)
		var order []byte
		for _, w := range addends {
			j := len(w) - 1 - i
			if j < 0 {
				continue
			}
			c := w[j]
			if counts[c] == 0 {
				order = append(order, c)
			}
			counts[c]++
		}
		col := column{}
		if i < len(result) {
			col.res = result[len(result)-1-i]
			col.hasRes = true
			if counts[col.res] == 0 && !containsLetter(order, col.res) {
				order = append(order, col.res)
			}
		}
		for _, c := range order {
			col.terms = append(col.terms, term{c, counts[c]})
		}
		cols[i] = col
	}

	assigned := make(map[byte]int)
	var used [10]bool
	var solve func(i, carry int) bool

	solve = func(i, carry int) bool {
		if i >= maxLen {
			return carry == 0
		}
		col := cols[i]

		base := carry
		var free []byte
		for _, t := range col.terms {
			if d, ok := assigned[t.letter]; ok {
				base += d * t.count
			} else {
				free = append(free, t.letter)
			}
		}

		// Order free letters so the result letter is resolved as early as possible.
		if col.hasRes {
			for k, c := range free {
				if c == col.res && k != 0 {
					copy(free[1:k+1], free[0:k])
					free[0] = c
					break
				}
			}
		} else {
			// No result letter at this column: the trailing digit must be zero.
			// Sort letters by coefficient, descending, for earlier pruning.
			for a := 1; a < len(free); a++ {
				for b := a; b > 0 && coeff(col, free[b]) > coeff(col, free[b-1]); b-- {
					free[b], free[b-1] = free[b-1], free[b]
				}
			}
		}

		var try func(k, sum int) bool
		try = func(k, sum int) bool {
			if k == len(free) {
				d := sum % 10
				nc := sum / 10
				if col.hasRes {
					if assigned[col.res] != d {
						return false
					}
				} else if d != 0 {
					return false
				}
				return solve(i+1, nc)
			}
			c := free[k]
			coef := coeff(col, c)
			for d := 0; d <= 9; d++ {
				if used[d] {
					continue
				}
				if d == 0 && leading[c] {
					continue
				}
				assigned[c] = d
				used[d] = true
				if try(k+1, sum+d*coef) {
					return true
				}
				delete(assigned, c)
				used[d] = false
			}
			return false
		}

		return try(0, base)
	}

	if !solve(0, 0) {
		return nil, errors.New("no solution")
	}

	out := make(map[string]int, len(assigned))
	for c, d := range assigned {
		out[string(c)] = d
	}
	return out, nil
}

func coeff(col column, letter byte) int {
	for _, t := range col.terms {
		if t.letter == letter {
			return t.count
		}
	}
	return 0
}

func containsLetter(list []byte, letter byte) bool {
	for _, c := range list {
		if c == letter {
			return true
		}
	}
	return false
}
EOF
